namespace sv_39e4c7cd0a1f48828070dd105c195c3e.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            CreateNotification("Welcome to the notification center!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New feature: dark mode is now available."),
        ]);
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>
    /// Returns only notifications newer than the given timestamp.
    /// Simulates a new notification appearing roughly every 10 seconds.
    /// </summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_notifications)
        {
            // Simulate a new notification arriving occasionally.
            if (Random.Shared.Next(0, 3) == 0)
            {
                var messages = new[]
                {
                    "Someone liked your post.",
                    "You have a new follower.",
                    "Server deployment completed.",
                    "Reminder: team standup in 15 minutes.",
                    "Your report is ready to download.",
                };
                _notifications.Add(
                    CreateNotification(messages[Random.Shared.Next(messages.Length)]));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Timestamp > since).ToList());
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using sv_39e4c7cd0a1f48828070dd105c195c3e.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    private List<Notification> notifications = [];
    private DateTime lastCheck = DateTime.MinValue;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        // Restore from prerender state, or load fresh.
        PersistedNotifications ??= await NotificationService.GetNotificationsAsync();
        notifications = PersistedNotifications;

        if (notifications.Count > 0)
        {
            lastCheck = notifications.Max(n => n.Timestamp);
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only starts after the component is interactive — never during prerender.
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), token);

            var newer = await NotificationService.GetNotificationsSinceAsync(lastCheck);
            if (newer.Count > 0)
            {
                notifications.AddRange(newer);
                lastCheck = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
    }
}

